23	class BlockMgr {
24	public:
25		BlockMgr(float overlapFraction = 1E-9f, bool hasReciprocal = false);
26		~BlockMgr();
27	
28		void getBlocks(RecordKeyVector &keyList, bool &mustDelete);
29		void deleteBlocks(RecordKeyVector &keyList);
30	
31		// Get the sum of the lengths of all blocks for a record.
32		CHRPOS getTotalBlockLength(RecordKeyVector &keyList);
33	
34		// Determine which hits in the hitList intersect the hits in the keyList by comparing all blocks in each
35		// and checking that their total intersection meets any overlapFraction and reciprocal criteria compared to
36		// the total block lengths of the hitList and keyList. All hits that pass will be in the resultList.
37		//
38		// If useOverlappingSubBlocks is true, resultList will contain the sub-intervals of the hit blocks 
39		// that overlap the query blocks.
40		//
41		// Return value is the number of hits in the result set.
42		int findBlockedOverlaps(RecordKeyVector &keyList, RecordKeyVector &hitList,
43								RecordKeyVector &resultList, RecordKeyVector *overlapList = NULL);
44	
45		//these are setting options for splitting BAM records
46		void setBreakOnDeletionOps(bool val) { _breakOnDeletionOps = val; }
47		void setBreakOnSkipOps(bool val) { _breakOnSkipOps = val; }
48		int getOverlapBases(int hitIdx) const { return _overlapBases[hitIdx]; }
49	
50		Record *allocateAndAssignRecord(const Record *keyRecord, CHRPOS startPos, CHRPOS endPos);
51	
52	
53	private:
54		RecordMgr *_blockRecordsMgr;
55		bool _breakOnDeletionOps;
56		bool _breakOnSkipOps;
57		vector<int> _overlapBases;
58	
59		float _overlapFraction;
60		bool _hasReciprocal;
61		Tokenizer _blockSizeTokens;
62		Tokenizer _blockStartTokens;
63	
64		// For now, all records will be split into Bed6 records.
65		const static FileRecordTypeChecker::RECORD_TYPE _blockRecordsType = FileRecordTypeChecker::BED6_RECORD_TYPE;
66		void getBlocksFromBed12(RecordKeyVector &keyList, bool &mustDelete);
67		void getBlocksFromBam(RecordKeyVector &keyList, bool &mustDelete);
68	
69	};
