33	void BlockMgr::getBlocks(RecordKeyVector &keyList, bool &mustDelete)
34	{
35		switch (keyList.getKey()->getType()) {
36		case FileRecordTypeChecker::BED12_RECORD_TYPE:
37			getBlocksFromBed12(keyList, mustDelete);
38			break;
39	
40		case FileRecordTypeChecker::BAM_RECORD_TYPE:
41			getBlocksFromBam(keyList, mustDelete);
42			break;
43	
44		default:
45			keyList.push_back(keyList.getKey());
46			mustDelete = false;
47			break;
48		}
49	}
50	
51	void BlockMgr::getBlocksFromBed12(RecordKeyVector &keyList, bool &mustDelete)
52	{
53		const Bed12Interval *keyRecord = static_cast<const Bed12Interval *>(keyList.getKey());
54		int blockCount = keyRecord->getBlockCount();
55	
56	    if ( blockCount <= 0 ) {
57	    	mustDelete = false;
58	    	return;
59	    }
60	
61	    int sizeCount = _blockSizeTokens.tokenize(keyRecord->getBlockSizes(), ',');
62	    int startCount = _blockStartTokens.tokenize(keyRecord->getBlockStarts(), ',');
63	
64	    if (blockCount != sizeCount || sizeCount != startCount) {
65	    	fprintf(stderr, "Error: found wrong block counts while splitting entry.\n");
66	    	exit(-1);
67	    }
68	
69	    for (int i=0; i < blockCount; i++) {
70	    	CHRPOS startPos = keyRecord->getStartPos() + str2chrPos(_blockStartTokens.getElem(i).c_str());
71	    	CHRPOS endPos = startPos + str2chrPos(_blockSizeTokens.getElem(i).c_str());
72	
73	    	Record *record = allocateAndAssignRecord(keyRecord, startPos, endPos);
74	    	keyList.push_back(record);
75	    }
76	    mustDelete = true;
77	}
78	
79	void BlockMgr::getBlocksFromBam(RecordKeyVector &keyList, bool &mustDelete)
80	{
81		const BamRecord *keyRecord = static_cast<const BamRecord *>(keyList.getKey());
82		const vector<BamTools::CigarOp> &cigarData = keyRecord->getCigarData();
83		CHRPOS currPos = keyRecord->getStartPos();
84		CHRPOS blockLength = 0;
85	
86		for (int i=0; i < (int)cigarData.size(); i++) {
87			char opType = cigarData[i].Type;
88			int opLen = (int)(cigarData[i].Length);
89	
90			switch(opType) {
91			case 'I':
92			case 'S':
93			case 'P':
94			case 'H':
95				break;
96			case 'M': case 'X': case '=':
97				blockLength += opLen;
98				break;
99			case 'D':
100			case 'N' :
101				if ((opType == 'D' && !_breakOnDeletionOps) ||
102						(opType == 'N' && !_breakOnSkipOps)) {
103					blockLength += opLen;
104				} else {
105					keyList.push_back(allocateAndAssignRecord(keyRecord, currPos, currPos + blockLength));
106					currPos += opLen + blockLength;
107					blockLength = 0;
108				}
109				break;
110			default:
111				fprintf(stderr, "ERROR: Found invalid Cigar operation: %c.\n", opType);
112				exit(1);
113				break;
114			}
115		}
116		if (blockLength > 0) {
117			keyList.push_back(allocateAndAssignRecord(keyRecord, currPos, currPos + blockLength));
118		}
119		mustDelete = true;
120	}
