122	Record *BlockMgr::allocateAndAssignRecord(const Record *keyRecord, CHRPOS startPos, CHRPOS endPos)
123	{
124		Record *record = _blockRecordsMgr->allocateRecord();
125		record->setChrName(keyRecord->getChrName());
126		record->setChromId(keyRecord->getChromId());
127		record->setStartPos(startPos);
128		record->setEndPos(endPos);
129		return record;
130	}
