36	void BinTree::getHits(Record *record, RecordKeyVector &hitSet)
37	{
38		if (record->isUnmapped()) {
39			return;
40		}
41	    const string &chr = record->getChrName();
42		mainMapType::iterator mainIter = _mainMap.find(chr);
43		if (mainIter == _mainMap.end()) {
44			//given chrom not even in map.
45			return;
46		}
47	
48	    binNumType startPos = record->getStartPos();
49	    binNumType endPos = record->getEndPos();
50	
51	    binNumType startBin = (startPos >> _binFirstShift);
52	    binNumType endBin = ((endPos-1) >> _binFirstShift);
53	
54	
55		allBinsType &bins = mainIter->second;
56	
57	    /* SYNOPSIS:
58	         1. We loop through each UCSC BIN level for feature A's chrom.
59	         2. For each BIN, we loop through each B feature and add it to
60	            hits if it meets all of the user's requests, which include:
61	               (a) overlap fraction, (b) strandedness, (c) reciprocal overlap
62	    */
63	    for (binNumType i = 0; i < NUM_BIN_LEVELS; i++) {
64	        binNumType offset = _binOffsetsExtended[i];
65	        for (binNumType j = (startBin+offset); j <= (endBin+offset); j++)  {
66	
67	        	// move to the next bin if this one is empty
68	        	allBinsType::iterator allBinsIter = bins.find(j);
69	        	if (allBinsIter == bins.end()) {
70	        		continue;
71	        	}
72	        	binType &bin = allBinsIter->second;
73	
74	        	for (binType::iterator iter = bin.begin(); iter != bin.end(); iter++) {
75	            	Record *dbRec = *iter;
76	            	if (record->intersects(dbRec,
77	                                       _context->getSameStrand(),
78	                                       _context->getDiffStrand(),
79	            			               _context->getOverlapFractionA(),
80	                                       _context->getOverlapFractionB(),
81	                                       _context->getReciprocalFraction(),
82	                                       _context->getEitherFraction()
83	                                      )
84	                    )
85	                {
86	            		hitSet.push_back(dbRec);
87	            	}
88	            }
89	        }
90	        startBin >>= _binNextShift;
91	        endBin >>= _binNextShift;
92	    }
93		if (_context->getSortOutput()) {
94			hitSet.sortVector();
95		}
96	}
