123	BinTree::binNumType BinTree::getBin(binNumType start, binNumType end) const {
124	    --end;
125	    start >>= _binFirstShift;
126	    end   >>= _binFirstShift;
127	
128	    for (binNumType i = 0; i < NUM_BIN_LEVELS; ++i) {
129	        if (start == end) {
130	        	return _binOffsetsExtended[i] + start;
131	        }
132	        start >>= _binNextShift;
133	        end   >>= _binNextShift;
134	    }
135	    //failure
136	    return -1;
137	}
