131	bool Record::intersects(const Record *record,
132	                        bool sameStrand,
133	                        bool diffStrand,
134	                        float overlapFractionA,
135	                        float overlapFractionB,
136	                        bool reciprocalFraction,
137	                        bool eitherFraction) const
138	{
139		//must be on same chromosome
140		if (!sameChrom(record)) {
141			return false;
142		}
143		return sameChromIntersects(record,
144	                               sameStrand, diffStrand,
145	                               overlapFractionA, overlapFractionB,
146	                               reciprocalFraction, eitherFraction);
147	}
148	
149	bool Record::sameChromIntersects(const Record *record,
150	                                 bool sameStrand,
151	                                 bool diffStrand,
152	                                 float overlapFractionA,
153	                                 float overlapFractionB,
154	                                 bool reciprocalFraction,
155	                                 bool eitherFraction) const
156	{
157		// Special: For records that are unmapped, intersect should automatically return false
158		if (_isUnmapped || record->isUnmapped()) {
159			return false;
160		}
161	
162		//If user requested hits only on same strand, or only on different strands,
163		//rule out different strandedness first.
164		//If the strand is unknown in either case, then queries regarding strandedness
165		//can not be answered, so we return false;
166		bool isSameStrand = (_strandVal == record->_strandVal && _strandVal != UNKNOWN);
167		bool isDiffStrand = ( _strandVal != UNKNOWN && record->_strandVal != UNKNOWN && _strandVal != record->_strandVal);
168	
169		if (sameStrand && !isSameStrand) {
170			return false; //want same, but they're not same.
171		}
172		if (diffStrand && !isDiffStrand) {
173			return false; //want different, but they're not different.
174		}
175		CHRPOS otherStart = record->getStartPos();
176		CHRPOS otherEnd = record->getEndPos();
177	
178		bool otherZeroLen = (otherStart - otherEnd == 0);
179		CHRPOS maxStart = max(_startPos, otherStart);
180		CHRPOS minEnd = min(_endPos, otherEnd);
181	
182		bool localZeroLen = (_endPos - _startPos == 0);
183		//rule out all cases of no intersection at all
184		if (minEnd < maxStart) {
185			return false;
186		}
187	
188		if ((overlapFractionA == 0.0) && (overlapFractionB == 0.0))
189	    {
190			//don't care about amount of overlap.
191			//however, if minEnd and maxStart are equal, and
192			//neither record is zeroLen, return false.
193			if (minEnd == maxStart && !otherZeroLen && !localZeroLen) {
194				return false;
195			}
196			return true;
197		}
198	
199		CHRPOS overlapBases = minEnd - maxStart;
200	        // Aaron: look here.
201		CHRPOS aLen = _endPos - _startPos;
202		CHRPOS bLen = otherEnd - otherStart;
203	
204	    float overlapA = (float)overlapBases / (float)aLen;
205	    float overlapB = (float)overlapBases / (float)bLen;
206	
207	    bool sufficentFractionA = (overlapA >= overlapFractionA);
208	    bool sufficentFractionB = (overlapB >= overlapFractionB);
209	
210	    if (!eitherFraction)
211	    {
212	        if (sufficentFractionA && sufficentFractionB) { return true; }
213	        return false;
214	    }
215	    else {
216	        if (sufficentFractionA || sufficentFractionB) { return true; }
217	        return false;
218	    }
219	
220		return false;
221	}
