37	bool NewChromSweep::init() {
38	
39	    //Create new FileRecordMgrs for the input files.
40	    //Open them, and get the first record from each.
41	    //otherwise, return true.
42	    _queryFRM = _context->getFile(_context->getQueryFileIdx());
43	
44	    _dbFRMs.resize(_numDBs, NULL);
45	    for (int i=0; i < _numDBs; i++) {
46	        _dbFRMs[i] = _context->getDatabaseFile(i);
47	    }
48	
49	    _currDbRecs.resize(_numDBs, NULL);
50	    if (!_context->hasGenomeFile()) 
51	    {
52	        _fileTracks.resize(_numFiles, NULL);
53	        for (int i=0; i < _numFiles; i++) 
54	        {
55	            _fileTracks[i] = new _orderTrackType;
56	        }
57	    }
58	
59	    for (int i=0; i < _numDBs; i++) {
60	        nextRecord(false, i);
61	        testChromOrder(_currDbRecs[i]);
62	    }
63	
64	    _caches.resize(_numDBs);
65	    _wasInitialized = true;
66	    return true;
67	 }
