142	void NewChromSweep::clearCache(int dbIdx)
143	{
144	    //delete all objects pointed to by cache
145	    recListType &cache = _caches[dbIdx];
146	    for (recListIterType iter = cache.begin(); iter != cache.end(); iter = cache.next()) 
147	    {
148	        _dbFRMs[dbIdx]->deleteRecord(iter->value());
149	    }
150	    cache.clear();
151	}
