153	void NewChromSweep::masterScan(RecordKeyVector &retList) {
154	
155	    for (int i=0; i < _numDBs; i++) 
156	    {
157	        if (dbFinished(i) || chromChange(i, retList, true)) 
158	        {
159	            continue;
160	        } 
161	        else 
162	        {
163	
164	            // scan the database cache for hits
165	            scanCache(i, retList);
166	            //skip if we hit the end of the DB
167	            // advance the db until we are ahead of the query. update hits and cache as necessary
168	            while (_currDbRecs[i] != NULL &&
169	                    _currQueryRec->sameChrom(_currDbRecs[i]) &&
170	                    !(_currDbRecs[i]->after(_currQueryRec))) 
171	            {
172	                if (intersects(_currQueryRec, _currDbRecs[i])) {
173	                    retList.push_back(_currDbRecs[i]);
174	                }
175	                if (_currQueryRec->after(_currDbRecs[i])) {
176	                    _dbFRMs[i]->deleteRecord(_currDbRecs[i]);
177	                    _currDbRecs[i] = NULL;
178	                } else {
179	                    _caches[i].push_back(_currDbRecs[i]);
180	                    _currDbRecs[i] = NULL;
181	                }
182	                nextRecord(false, i);
183	            }
184	        }
185	    }
186	}
187	
188	bool NewChromSweep::chromChange(int dbIdx, RecordKeyVector &retList, bool wantScan)
189	{
190	    const Record *dbRec = _currDbRecs[dbIdx];
191	
192	    if (_currQueryRec != NULL && _currQueryChromName != _prevQueryChromName) {
193	        _context->testNameConventions(_currQueryRec);
194	        testChromOrder(_currQueryRec);
195	    }
196	
197	    if (dbRec != NULL) {
198	        _context->testNameConventions(dbRec);
199	        testChromOrder(dbRec);
200	    }
201	
202	    // If the query rec and db rec are on the same chrom, stop.
203	    if (dbRec != NULL && _currQueryRec != NULL && _currQueryRec->sameChrom(dbRec)) return false;
204	
205	
206	    if (dbRec == NULL || _currQueryRec == NULL) return false;
207	
208	    if (queryChromAfterDbRec(dbRec)) {
209	        // the query is ahead of the database. fast-forward the database to catch-up.
210	        string oldDbChrom(dbRec->getChrName());
211	        while (dbRec != NULL && queryChromAfterDbRec(dbRec)) 
212	        {
213	            _dbFRMs[dbIdx]->deleteRecord(dbRec);
214	            if (!nextRecord(false, dbIdx)) break;
215	            dbRec =  _currDbRecs[dbIdx];
216	            const string &newDbChrom = dbRec->getChrName();
217	            if (newDbChrom != oldDbChrom) {
218	                testChromOrder(dbRec);
219	                oldDbChrom = newDbChrom;
220	            }
221	        }
222	        clearCache(dbIdx);
223	        return false;
224	    } else {
225	        // the database is ahead of the query.
226	        // scan the cache for remaining hits on the query's current chrom.
227	        if (wantScan) scanCache(dbIdx, retList);
228	        return true;
229	    }
230	}
