268	bool NewChromSweep::nextRecord(bool query, int dbIdx) {
269	    if (query) {
270	        _currQueryRec = _queryFRM->getNextRecord();
271	        if (_currQueryRec != NULL) {
272	            _queryRecordsTotalLength += (unsigned long)(_currQueryRec->getLength(_context->getObeySplits()));
273	            _queryTotalRecords++;
274	            return true;
275	        }
276	        return false;
277	    } else { //database
278	        Record *rec = _dbFRMs[dbIdx]->getNextRecord();
279	        _currDbRecs[dbIdx] = rec;
280	        if (rec != NULL) {
281	            _databaseRecordsTotalLength += (unsigned long)(rec->getLength(_context->getObeySplits()));
282	            _databaseTotalRecords++;
283	            return true;
284	        }
285	        return false;
286	    }
287	}
