460	bool NewChromSweep::testLexicoQueryAfterDb(const Record *queryRec, const Record *dbRec)
461	{
462	    if (_lexicoDisproven) return false;
463	
464	    bool queryGreater = queryRec->getChrName() > dbRec->getChrName();
465	    if (!_lexicoAssumed && queryGreater) {
466	        _lexicoAssumed = true;
467	        _lexicoAssumedFileIdx = dbRec->getFileIdx();
468	        _lexicoAssumedChromName = dbRec->getChrName();
469	    }
470	    return queryGreater;
471	}

