class BlockMgr {
public:
	BlockMgr(float overlapFractionA = 1E-9f, float overlapFractionB = 1E-9f,
			 bool hasReciprocal = false, bool eitherFraction = false);
	~BlockMgr();

	void getBlocks(RecordKeyVector &keyList, bool &mustDelete);
	void deleteBlocks(RecordKeyVector &keyList);

	// Get the sum of the lengths of all blocks for a record.
	CHRPOS getTotalBlockLength(RecordKeyVector &keyList);

	// Determine which hits in the hitList intersect the blocks of the keyList by comparing all blocks in each.
	// A hit's fraction (the fraction of the hit record that overlaps the query blocks) is always evaluated
	// per hit, using the hit's own block lengths.
	// The query's fraction is evaluated against the total overlap of the query's blocks. When the query
	// record is discontinuous (it split into more than one block, e.g. a spliced BED12 or BAM record), the
	// overlap of every hit counts toward the fraction of the whole query record; when the query record is
	// continuous, the fraction is evaluated per hit, exactly as for unsplit records.
	// The reciprocal and either/fraction requirements follow the documented -r and -e semantics.
	// All hits that pass will be in the resultList.
	//
	// If overlapList is not NULL, overlapList will also receive the sub-intervals of the query's blocks
	// overlapping each hit that passed.
	//
	// Return value is the number of hits in the result set.
	int findBlockedOverlaps(RecordKeyVector &keyList, RecordKeyVector &hitList,
							RecordKeyVector &resultList, RecordKeyVector *overlapList = NULL);

	//these are setting options for splitting BAM records
	void setBreakOnDeletionOps(bool val) { _breakOnDeletionOps = val; }
	void setBreakOnSkipOps(bool val) { _breakOnSkipOps = val; }
	int getOverlapBases(int hitIdx) const { return _overlapBases[hitIdx]; }

	Record *allocateAndAssignRecord(const Record *keyRecord, CHRPOS startPos, CHRPOS endPos);


private:
	RecordMgr *_blockRecordsMgr;
	bool _breakOnDeletionOps;
	bool _breakOnSkipOps;
	vector<int> _overlapBases;

	float _overlapFractionA;
	float _overlapFractionB;
	bool _hasReciprocal;
	bool _eitherFraction;

