int BlockMgr::findBlockedOverlaps(RecordKeyVector &keyList, RecordKeyVector &hitList,
	                              RecordKeyVector &resultList, RecordKeyVector *overlapList)
{
	bool deleteKeyBlocks = false;
	if (keyList.empty()) {
		//get all the blocks for the query record, put them in it's list.
		getBlocks(keyList, deleteKeyBlocks);
	}
	_overlapBases.clear();
	CHRPOS keyBlocksSumLength = getTotalBlockLength(keyList);

	// A query record that split into more than one block is discontinuous
	// (e.g. a spliced BAM read or multi-block BED12 feature). For such records
	// the overlap fraction of the query is measured against the total block
	// overlap with all database records, rather than against each database
	// record separately.
	bool keyIsDiscontinuous = (keyList.size() > 1);

	// The fraction of each hit is always tested per database record. With the
	// reciprocal option, the same fraction as the query's applies.
	float hitFractionRequired = _hasReciprocal ? _overlapFractionA : _overlapFractionB;

	// Per database record measurements, kept in hitList order.
	vector<Record *> hitsWithOverlap;
	vector<CHRPOS> hitOverlapBases;
	vector<CHRPOS> hitBlockSumLengths;
	vector<vector<Record *> > hitOverlapIntervals;
	CHRPOS totalKeyOverlap = 0;

	//Loop through every database record the query intersected with
	RecordKeyVector::iterator_type hitListIter = hitList.begin();
	for (; hitListIter != hitList.end(); hitListIter = hitList.next())
	{
		RecordKeyVector hitBlocks(*hitListIter);
		bool deleteHitBlocks = false;
		getBlocks(hitBlocks, deleteHitBlocks); //get all blocks for the hit record.
		CHRPOS hitBlockSumLength = getTotalBlockLength(hitBlocks); //get total length of the bocks for the hitRecord.
		CHRPOS totalHitOverlap = 0;
		vector<Record *> subRecords;

		//loop through every block of the database record.
		RecordKeyVector::iterator_type hitBlockIter = hitBlocks.begin();
		for (; hitBlockIter != hitBlocks.end(); hitBlockIter = hitBlocks.next())
		{
			//loop through every block of the query record.
			RecordKeyVector::iterator_type keyListIter = keyList.begin();
			for (; keyListIter != keyList.end(); keyListIter = keyList.next())
			{
				const Record *keyBlock = *keyListIter;
				const Record *hitBlock = *hitBlockIter;

				CHRPOS maxStart = max(keyBlock->getStartPos(), hitBlock->getStartPos());
				CHRPOS minEnd = min(keyBlock->getEndPos(), hitBlock->getEndPos());
				CHRPOS overlap  = minEnd - maxStart;
				if (overlap > 0) {
					if (overlapList != NULL) {
						subRecords.push_back(allocateAndAssignRecord(keyList.getKey(), maxStart, minEnd));
					}
					totalHitOverlap += overlap;
				}
			}
		}
		if (deleteHitBlocks) {
			deleteBlocks(hitBlocks);
		}
		if (totalHitOverlap > 0) {
			hitsWithOverlap.push_back(*hitListIter);
			hitOverlapBases.push_back(totalHitOverlap);
			hitBlockSumLengths.push_back(hitBlockSumLength);
			if (overlapList != NULL) {
				hitOverlapIntervals.push_back(subRecords);
			}
			totalKeyOverlap += totalHitOverlap;
		}
	}
	if (deleteKeyBlocks) {
		deleteBlocks(keyList);
	}

	// Fraction of the query record's blocks overlapped by the database.
	// For a discontinuous query, every hit's overlap counts toward the whole.
	float keyOverlapFraction = (float)totalKeyOverlap / (float)keyBlocksSumLength;

	for (size_t i = 0; i < hitsWithOverlap.size(); i++) {
		float fractionA = keyIsDiscontinuous ? keyOverlapFraction
											 : (float)hitOverlapBases[i] / (float)keyBlocksSumLength;
		float fractionB = (float)hitOverlapBases[i] / (float)hitBlockSumLengths[i];

		bool sufficientFractionA = (fractionA >= _overlapFractionA);
		bool sufficientFractionB = (fractionB >= hitFractionRequired);
		bool pass = _eitherFraction ? (sufficientFractionA || sufficientFractionB)
									: (sufficientFractionA && sufficientFractionB);
		if (pass) {
			_overlapBases.push_back((int)hitOverlapBases[i]);
			resultList.push_back(hitsWithOverlap[i]);
			if (overlapList != NULL) {
				for (size_t j = 0; j < hitOverlapIntervals[i].size(); j++) {
					overlapList->push_back(hitOverlapIntervals[i][j]);
				}
			}
		} else {
			for (size_t j = 0; j < hitOverlapIntervals[i].size(); j++) {
				_blockRecordsMgr->deleteRecord(hitOverlapIntervals[i][j]);
			}
		}
	}

	resultList.setKey(keyList.getKey());
	return (int)resultList.size();
}

