/* Minimal samtools "view" stand-in for the bedtools test suite.
 * usage:
 *   samconv out SAMFILE            -> write SAM text to stdout (BAM input allowed)
 *   samconv -Sb SAMFILE            -> write BAM to stdout
 *   samconv view -                 -> BAM from stdin to SAM on stdout
 *   samconv view -Sb FILE or -     -> SAM to BAM on stdout
 */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "htslib/sam.h"

int main(int argc, char **argv)
{
    int toBam = 0;
    const char *inPath = NULL;
    int a = 1;
    /* accept optional subcommand "view" */
    if (a < argc && strcmp(argv[a], "view") == 0) a++;
    for (; a < argc; a++) {
        if (strcmp(argv[a], "-Sb") == 0 || strcmp(argv[a], "-b") == 0) {
            if (strcmp(argv[a], "-b") == 0) continue; /* -b alone means BAM out */
            toBam = 1;
        } else if (strcmp(argv[a], "-S") == 0) {
            continue;
        } else if (argv[a][0] == '-' && argv[a][1] != '\0') {
            fprintf(stderr, "samconv: unsupported flag %s\n", argv[a]);
            return 2;
        } else {
            inPath = argv[a];
        }
    }
    const char *mode = toBam ? "wb" : "r";
    samFile *in = sam_open(inPath ? inPath : "-", "r");
    if (!in) { fprintf(stderr, "samconv: cannot open input\n"); return 1; }
    sam_hdr_t *hdr = sam_hdr_read(in);
    if (!hdr) { fprintf(stderr, "samconv: no header\n"); return 1; }
    samFile *out = sam_open("-", mode);
    if (!out) { fprintf(stderr, "samconv: cannot open stdout\n"); return 1; }
    if (sam_hdr_write(out, hdr) < 0) { fprintf(stderr, "samconv: hdr write failed\n"); return 1; }
    bam1_t *rec = bam_init1();
    while (sam_read1(in, hdr, rec) >= 0) {
        if (!toBam) {
            /* render SAM */
            kstring_t ks = {0, 0, NULL};
            if (sam_format1(hdr, rec, &ks) < 0) { free(ks.s); continue; }
            fwrite(ks.s, 1, ks.l, out->fp.hfp);
            fputc('\n', out->fp.hfp);
            free(ks.s);
        } else {
            sam_write1(out, hdr, rec);
        }
    }
    bam_destroy1(rec);
    sam_hdr_destroy(hdr);
    sam_close(in);
    sam_close(out);
    return 0;
}
